mapper.select:
SELECT room_id, message_id, sender_id, sender_name, sender_type, message_role, content, is_preempted, create_time FROM ai_chat_room_message WHERE room_id = #{roomId} AND is_deleted = 0
AND create_time < FROM_UNIXTIME(#{cursorTime}/1000)
ORDER BY create_time DESC, id DESC LIMIT #{limit}
